    "content": "<div class=\"ml-en\"><span class=\"eyebrow\">IAM302 · Assessments</span>\n<h2>When you are tested</h2></div>\n<div class=\"ml-vi\"><span class=\"eyebrow\">IAM302 · Kiểm tra & thi</span>\n<h2>Khi nào bị kiểm tra</h2></div>\n<table><thead><tr><th>Session<br><small>Buổi</small></th><th>Topic<br><small>Nội dung</small></th><th>LO</th></tr></thead><tbody>\n<tr><td><strong>5</strong></td><td>Lab 1: Setting Up Environment</td><td>LO1, LO4</td></tr>\n<tr><td><strong>6</strong></td><td>Lab 1: Setting Up Environment (cont.)</td><td>LO1, LO4</td></tr>\n<tr><td><strong>9</strong></td><td>Lab 2: Examining ClamAV Signature</td><td>LO2, LO5</td></tr>\n<tr><td><strong>10</strong></td><td>Lab 2: Examining ClamAV Signature (cont.)</td><td>LO2, LO5</td></tr>\n<tr><td><strong>11</strong></td><td>Lab 3: Creating Custom ClamAV Databases</td><td>LO2, LO5</td></tr>\n<tr><td><strong>12</strong></td><td>Lab 3: Creating Custom ClamAV Databases (cont.)</td><td>LO2, LO5</td></tr>\n<tr><td><strong>13</strong></td><td>Lab 4: Detect Malware Capabilities with YARA (a difference with ClamAV)</td><td>LO2, LO5</td></tr>\n<tr><td><strong>14</strong></td><td>Lab 4: Detect Malware Capabilities with YARA (a difference with ClamAV) (cont.)</td><td>LO2, LO5</td></tr>\n<tr><td><strong>17</strong></td><td>Lab 5: Sandbox Setup and Configuration</td><td>LO4, LO6</td></tr>\n<tr><td><strong>18</strong></td><td>Lab 5: Sandbox Setup and Configuration (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>19</strong></td><td>Lab 6: Public AV Scanners (VirusTotal, Jotti)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>20</strong></td><td>Lab 6: Public AV Scanners (VirusTotal, Jotti) (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>21</strong></td><td>Lab 7: MA with CWSandbox, Anubis</td><td>LO4, LO6</td></tr>\n<tr><td><strong>22</strong></td><td>Lab 7: MA with CWSandbox, Anubis (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>23</strong></td><td>Review Topics 1-4 (Guiding Problems)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>24</strong></td><td>Progress Test 1 (30’)</td><td></td></tr>\n<tr><td><strong>26</strong></td><td>Lab 8: Configuring a Malware Lab</td><td>LO4, LO6</td></tr>\n<tr><td><strong>27</strong></td><td>Lab 9: Recipe Manipulating HTTP/HTTPS with Burp Suite<br><br>Reading: Recipe 7-5 - Using Joe Stewart’s Truman</td><td>LO4, LO6</td></tr>\n<tr><td><strong>28</strong></td><td>Lab 9: Recipe Manipulating HTTP/HTTPS with Burp Suite<br><br>Reading: Recipe 7-5 - Using Joe Stewart’s Truman (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>29</strong></td><td>Lab 10: Using Deep Freeze to Preserve Physical Systems</td><td>LO4, LO6</td></tr>\n<tr><td><strong>30</strong></td><td>Lab 10: Using Deep Freeze to Preserve Physical Systems (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>31</strong></td><td>Lab 11: Using FOG for Cloning and Imaging Disks</td><td>LO4, LO6</td></tr>\n<tr><td><strong>32</strong></td><td>Lab 11: Using FOG for Cloning and Imaging Disks (cont.)</td><td>LO4, LO6</td></tr>\n<tr><td><strong>35</strong></td><td>Lab 12: Dynamic Analysis Tools (Process Monitor, Regshot, HandleDiff)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>36</strong></td><td>Lab 12: Dynamic Analysis Tools (Process Monitor, Regshot, HandleDiff) (cont.)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>37</strong></td><td>Lab 13: Analysis Automation Tools: VirtualBox, VMWare, TShark, …</td><td>LO5, LO7</td></tr>\n<tr><td><strong>38</strong></td><td>Lab 13: Analysis Automation Tools: VirtualBox, VMWare, TShark, … (cont.)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>40</strong></td><td>Lab 14: Using TSK for Network and Host</td><td>LO8</td></tr>\n<tr><td><strong>41</strong></td><td>Lab 15: Identifying Packers using PEiD</td><td>LO8</td></tr>\n<tr><td><strong>42</strong></td><td>Lab 15: Identifying Packers using PEiD (cont.)</td><td>LO8</td></tr>\n<tr><td><strong>43</strong></td><td>Lab16: Registry Forensics with RegRipper Plug-ins</td><td>LO8</td></tr>\n<tr><td><strong>44</strong></td><td>Lab16: Registry Forensics with RegRipper Plug-ins (cont.)</td><td>LO8</td></tr>\n<tr><td><strong>47</strong></td><td>Review Topics 5-7 (Guiding Problems)</td><td></td></tr>\n<tr><td><strong>48</strong></td><td>Progress Test 2 (30’)</td><td></td></tr>\n<tr><td><strong>51</strong></td><td>Lab 17: Implementing a JIT (just-in-time) Debugger for Shellcode Analysis</td><td>LO5, LO7</td></tr>\n<tr><td><strong>52</strong></td><td>Lab 17: Implementing a JIT (just-in-time) Debugger for Shellcode Analysis (cont.)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>55</strong></td><td>Lab 18: Memory Dump Tool (MoonSols Windows Memory Toolkit)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>56</strong></td><td>Lab 18: Memory Dump Tool (MoonSols Windows Memory Toolkit) (cont.)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>57</strong></td><td>Lab 19: Memory Analysis Tool (Volatility Framework)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>58</strong></td><td>Lab 19: Memory Analysis Tool (Volatility Framework) (cont.)</td><td>LO5, LO7</td></tr>\n<tr><td><strong>59</strong></td><td>Course Review</td><td></td></tr>\n<tr><td><strong>60</strong></td><td>Course Review (cont.)</td><td></td></tr>\n</tbody></table>"
